create extension if not exists pgcrypto;
create type public.academic_year_state as enum ('draft','active','closed');
create type public.membership_category as enum ('incumbent','alumni','student_advisor','staff_advisor','other');
create type public.appointment_position as enum ('president','vice_president','secretary','welfare_fundraising_manager','external_events_director','internal_events_director','content_creation_publicity_director','executive','student_advisor','staff_advisor');
create type public.appointment_state as enum ('pending','active','retired','cancelled');
create type public.capability_name as enum ('calendar_edit','public_event_prepare','public_event_publish','task_manage','committee_manage','handover_execute','attachment_read');
create type public.grant_scope as enum ('global','semester','event');
create type public.event_type as enum ('industry','visit','extpartner','bonding','external');
create type public.event_status as enum ('potential','contacted','discussion','confirmed','completed','declined');
create type public.task_visibility as enum ('all_members','assigned_team');
create type public.publication_state as enum ('draft','published','unpublished');

create table public.profiles (id uuid primary key references auth.users(id) on delete restrict, display_name text not null check(length(trim(display_name))>0), nus_department text, study_year smallint check(study_year between 1 and 10), hobbies text, experience text, revision bigint not null default 1 check(revision>0), created_at timestamptz not null default statement_timestamp(), created_by uuid not null references auth.users, updated_at timestamptz not null default statement_timestamp(), updated_by uuid not null references auth.users, deleted_at timestamptz, deleted_by uuid references auth.users, check((deleted_at is null)=(deleted_by is null)));
create table public.verified_emails (id uuid primary key default gen_random_uuid(), profile_id uuid not null references profiles, email text not null, is_nus boolean not null, verified_at timestamptz not null, verified_by uuid not null references auth.users);
create unique index verified_emails_normalized_email_key on public.verified_emails(lower(email));
create table public.academic_years (id uuid primary key default gen_random_uuid(), label text not null unique, starts_on date not null, ends_on date not null, timezone text not null default 'Asia/Singapore' check(timezone='Asia/Singapore'), lifecycle academic_year_state not null default 'draft', semester_one_start date not null, semester_one_end date not null, semester_two_start date not null, semester_two_end date not null, check(ends_on>=starts_on), check(semester_one_end>=semester_one_start), check(semester_two_end>=semester_two_start));
create table public.memberships (id uuid primary key default gen_random_uuid(), profile_id uuid not null references profiles, academic_year_id uuid not null references academic_years, category membership_category not null, starts_on date not null, ends_on date, verified_by uuid not null references auth.users, check(ends_on is null or ends_on>=starts_on), unique(profile_id,academic_year_id,category,starts_on));
create table public.committees (id uuid primary key default gen_random_uuid(), academic_year_id uuid not null unique references academic_years, name text not null, operational_from timestamptz not null, state appointment_state not null default 'pending', handover_preview jsonb, handover_confirmed_at timestamptz, recovery_snapshot jsonb);
create table public.teams (id uuid primary key default gen_random_uuid(), committee_id uuid not null references committees, code text not null, display_name text not null, starts_on date not null, ends_on date, unique(committee_id,code), unique(committee_id,display_name), check(ends_on is null or ends_on>=starts_on));
create table public.appointments (id uuid primary key default gen_random_uuid(), profile_id uuid not null references profiles, committee_id uuid not null references committees, team_id uuid references teams, position appointment_position not null, state appointment_state not null default 'pending', starts_at timestamptz not null, ends_at timestamptz, appointed_by uuid not null references auth.users, check(ends_at is null or ends_at>=starts_at));

create table public.events (id uuid primary key default gen_random_uuid(), academic_year_id uuid not null references academic_years, legacy_id text, semester smallint not null check(semester in(1,2)), name text not null check(length(trim(name))>0), type event_type not null, status event_status not null, all_day boolean not null, starts_on date, ends_on date, starts_at timestamptz, ends_at timestamptz, timezone text not null default 'Asia/Singapore' check(timezone='Asia/Singapore'), venue text not null default '', description text not null default '', expected_attendance integer check(expected_attendance>=0), actual_attendance integer check(actual_attendance>=0), budget numeric(12,2) check(budget>=0), revision bigint not null default 1 check(revision>0), created_at timestamptz not null default statement_timestamp(), created_by uuid not null references auth.users, updated_at timestamptz not null default statement_timestamp(), updated_by uuid not null references auth.users, deleted_at timestamptz, deleted_by uuid references auth.users, unique(academic_year_id,legacy_id), check((all_day and starts_on is not null and starts_at is null and ends_at is null) or (not all_day and starts_on is null and ends_on is null and starts_at is not null)), check((all_day and coalesce(ends_on,starts_on)>=starts_on) or (not all_day and (ends_at is null or ends_at>=starts_at))), check((deleted_at is null)=(deleted_by is null)));
create table public.capability_grants (id uuid primary key default gen_random_uuid(), grantee_id uuid not null references profiles, capability capability_name not null, scope grant_scope not null, academic_year_id uuid references academic_years, semester smallint check(semester in(1,2)), event_id uuid references events, starts_at timestamptz not null, expires_at timestamptz, granted_by uuid not null references auth.users, revoked_at timestamptz, revoked_by uuid references auth.users, check(expires_at is null or expires_at>=starts_at), check((revoked_at is null)=(revoked_by is null)), check((scope='global' and semester is null and event_id is null) or (scope='semester' and academic_year_id is not null and semester is not null and event_id is null) or (scope='event' and event_id is not null and semester is null)));
create table public.trek_entitlements (id uuid primary key default gen_random_uuid(), profile_id uuid not null references profiles, academic_year_id uuid not null references academic_years, semester smallint check(semester in(1,2)), starts_at timestamptz not null, expires_at timestamptz, granted_by uuid not null references auth.users, reason text not null, check(expires_at is null or expires_at>=starts_at));
create table public.event_team_assignments(event_id uuid references events on delete restrict, team_id uuid references teams on delete restrict, primary key(event_id,team_id));
create table public.planning_tasks (id uuid primary key default gen_random_uuid(), event_id uuid references events, title text not null, description text not null default '', visibility task_visibility not null default 'assigned_team', owner_id uuid references profiles, due_at timestamptz, completed_at timestamptz, revision bigint not null default 1 check(revision>0), created_at timestamptz not null default statement_timestamp(), created_by uuid not null references auth.users, updated_at timestamptz not null default statement_timestamp(), updated_by uuid not null references auth.users, deleted_at timestamptz, deleted_by uuid references auth.users, check((deleted_at is null)=(deleted_by is null)));
create table public.task_team_assignments(task_id uuid references planning_tasks on delete restrict,team_id uuid references teams on delete restrict,primary key(task_id,team_id));
create table public.task_assignees(task_id uuid references planning_tasks on delete restrict,profile_id uuid references profiles on delete restrict,primary key(task_id,profile_id));
create table public.event_links(id uuid primary key default gen_random_uuid(),event_id uuid not null references events,label text not null,url text not null check(url~'^https?://'));
create table public.attachment_metadata(id uuid primary key default gen_random_uuid(),event_id uuid references events,task_id uuid references planning_tasks,storage_bucket text not null,storage_path text not null,mime_type text not null,byte_size bigint not null check(byte_size>=0),uploaded_at timestamptz not null default statement_timestamp(),uploaded_by uuid not null references auth.users,check((event_id is not null)::int+(task_id is not null)::int=1),unique(storage_bucket,storage_path));
create table public.public_event_publications(id uuid primary key default gen_random_uuid(),source_event_id uuid references events,poster_attachment_id uuid references attachment_metadata,promotional_copy text not null,signup_url text check(signup_url is null or signup_url~'^https?://'),display_order integer not null default 0,publish_from timestamptz,publish_until timestamptz,state publication_state not null default 'draft',revision bigint not null default 1,created_at timestamptz not null default statement_timestamp(),created_by uuid not null references auth.users,updated_at timestamptz not null default statement_timestamp(),updated_by uuid not null references auth.users,deleted_at timestamptz,deleted_by uuid references auth.users,check(publish_until is null or publish_from is null or publish_until>=publish_from));
create table public.public_event_recaps(id uuid primary key default gen_random_uuid(),source_event_id uuid references events,recap_text text not null,media_attachment_id uuid references attachment_metadata,occurred_on date not null,state publication_state not null default 'draft',revision bigint not null default 1,created_at timestamptz not null default statement_timestamp(),created_by uuid not null references auth.users,updated_at timestamptz not null default statement_timestamp(),updated_by uuid not null references auth.users,deleted_at timestamptz,deleted_by uuid references auth.users);
create table public.audit_entries(id bigint generated always as identity primary key,occurred_at timestamptz not null default statement_timestamp(),actor_id uuid references auth.users,action text not null,entity_type text not null,entity_id uuid,entity_revision bigint,transaction_id bigint not null default txid_current(),before_data jsonb,after_data jsonb,metadata jsonb not null default '{}');
create table public.import_runs(id uuid primary key default gen_random_uuid(),academic_year_id uuid not null references academic_years,status text not null check(status in('previewed','confirmed','rolled_back','failed')),source_digest text not null unique,pre_import_snapshot jsonb not null,rejected_records jsonb not null default '[]',reconciliation jsonb,created_at timestamptz not null default statement_timestamp(),created_by uuid not null references auth.users,confirmed_at timestamptz,rolled_back_at timestamptz);
